from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()

MARKETPLACE = r"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AutoFlow — найти автосервис</title>
<style>
:root{font-family:Inter,Segoe UI,Arial,sans-serif;color:#172333;background:#f4f7f8}*{box-sizing:border-box}body{margin:0}header{background:#101d2b;color:#fff;padding:18px max(5vw,20px);display:flex;justify-content:space-between;align-items:center}.brand{font-size:24px;font-weight:850;letter-spacing:-1px}.brand span{color:#6ed49d}a{color:inherit;text-decoration:none}.wrap{max-width:1180px;margin:auto;padding:32px 20px}.hero{padding:42px;border-radius:24px;background:linear-gradient(120deg,#12283a,#234e50);color:white}.hero h1{font-size:clamp(30px,5vw,52px);line-height:1.04;max-width:720px;margin:0 0 12px}.hero p{color:#c5d6dc;max-width:600px}.search{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px;margin-top:25px}.search input,.search select{padding:14px;border:1px solid #d4dde3;border-radius:10px;background:white;font:inherit;min-width:0}.btn{border:0;border-radius:10px;padding:13px 18px;background:#71d5a0;color:#10251b;font-weight:800;cursor:pointer}.btn.dark{background:#172c3b;color:#fff}.section{margin:34px 0 16px;display:flex;justify-content:space-between;align-items:end;gap:12px}.section h2{margin:0;font-size:25px}.muted{color:#68798a}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid #e0e7ea;border-radius:16px;padding:20px;box-shadow:0 8px 24px #162d3b0a}.card h3{margin:0 0 6px}.chip{display:inline-block;background:#e8f7ef;color:#20764a;border-radius:20px;padding:5px 9px;font-size:12px;font-weight:700}.price{font-size:22px;font-weight:800;margin:12px 0}.card .btn{width:100%;margin-top:12px}.empty{padding:35px;text-align:center;color:#68798a;background:white;border-radius:16px}.toplink{color:#c9d7df;font-size:14px}@media(max-width:850px){.search{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.hero{padding:26px}.search,.grid{grid-template-columns:1fr}.wrap{padding:22px 14px}.section{align-items:start;flex-direction:column}}
</style></head><body>
<header><a class="brand" href="/marketplace">Auto<span>Flow</span></a><div class="row"><a class="toplink" href="/">Кабинет автосервиса</a></div></header>
<main class="wrap"><section class="hero"><span class="chip">САНКТ-ПЕТЕРБУРГ · ЛЕНИНГРАДСКАЯ ОБЛАСТЬ</span><h1>Найдите автосервис. Запишитесь без звонков.</h1><p>Сравнивайте услуги и цены, выбирайте удобный сервис и отправляйте заявку на запись онлайн.</p>
<form id="search" class="search"><input name="q" placeholder="Услуга или название автосервиса"><select name="city"><option value="">Все города</option><option>Санкт-Петербург</option><option>Всеволожск</option><option>Гатчина</option><option>Выборг</option><option>Кудрово</option><option>Мурино</option></select><select name="category"><option value="">Все услуги</option><option>ТО</option><option>Диагностика</option><option>Ремонт двигателя</option><option>Шиномонтаж</option><option>Тормозная система</option><option>Электрика</option></select><button class="btn">Найти</button></form></section>
<div class="section"><div><h2>Автосервисы и услуги</h2><div class="muted">Выбирайте подходящий вариант и отправляйте заявку</div></div><span id="count" class="muted"></span></div><div id="results" class="grid"><div class="empty">Загружаем каталог…</div></div></main>
<script>
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function load(){const f=new FormData($('#search'));const p=new URLSearchParams();for(const [k,v] of f)if(v.trim())p.set(k,v.trim());try{const r=await fetch('/api/marketplace/services?'+p);const data=await r.json();$('#count').textContent=data.length+' предложений';$('#results').innerHTML=data.length?data.map(x=>'<article class="card"><span class="chip">'+esc(x.category)+'</span><h3>'+esc(x.business)+'</h3><div class="muted">'+esc(x.city)+(x.district?' · '+esc(x.district):'')+' · '+esc(x.address)+'</div><h3 style="margin-top:16px">'+esc(x.service)+'</h3><div class="muted">'+esc(x.description||'Услуга автосервиса')+'</div><div class="price">'+(x.price_from_rub===null?'Цена по запросу':'от '+Number(x.price_from_rub).toLocaleString('ru-RU')+' ₽')+'</div><div class="muted">Ориентировочно '+x.duration_minutes+' минут · '+esc(x.phone)+'</div><button class="btn" data-service-id="'+x.service_id+'" data-service="'+esc(x.service)+'" data-business="'+esc(x.business)+'" onclick="book(this)">Записаться</button></article>').join(''):'<div class="empty" style="grid-column:1/-1">Пока нет опубликованных предложений. Попробуйте изменить фильтры или вернитесь позже.</div>'}catch(e){$('#results').innerHTML='<div class="empty">Не удалось загрузить каталог. Обновите страницу.</div>'}}
async function book(button){const id=Number(button.dataset.serviceId),service=button.dataset.service,business=button.dataset.business;const name=prompt('Ваше имя для записи на «'+service+'» в '+business);if(!name)return;const phone=prompt('Номер телефона для связи с автосервисом');if(!phone)return;const day=prompt('Выберите дату (ГГГГ-ММ-ДД)');if(!day)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(day)){alert('Введите дату в формате ГГГГ-ММ-ДД');return}try{const offset=-new Date().getTimezoneOffset();const availability=await fetch('/api/marketplace/availability?'+new URLSearchParams({service_id:id,day,utc_offset_minutes:offset}));const slotsData=await availability.json();if(!availability.ok)throw Error(slotsData.detail||'Не удалось проверить свободное время');if(!slotsData.slots.length){alert('На эту дату свободного времени нет. Выберите другой день.');return}const choices=slotsData.slots.map((slot,i)=>(i+1)+'. '+new Date(slot).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})).join('\n');const choice=Number(prompt('Свободное время ('+slotsData.working_hours.from+'–'+slotsData.working_hours.to+'):\n'+choices+'\n\nВведите номер подходящего времени'));if(!Number.isInteger(choice)||choice<1||choice>slotsData.slots.length)return;const starts_at=slotsData.slots[choice-1];const r=await fetch('/api/marketplace/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:id,customer_name:name,customer_phone:phone,starts_at})});const d=await r.json();if(!r.ok)throw Error(d.detail||'Не удалось создать запись');alert('Заявка №'+d.id+' отправлена! Автосервис должен подтвердить время.')}catch(e){alert(e.message)}}
$('#search').addEventListener('submit',e=>{e.preventDefault();load()});load();
</script></body></html>
"""

@router.get("/marketplace", response_class=HTMLResponse, include_in_schema=False)
def marketplace_home():
    return MARKETPLACE

PARTNER = r"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoFlow — кабинет партнёра</title>
<style>body{margin:0;background:#0b1421;color:#eaf0f7;font:15px Inter,Segoe UI,Arial}header{padding:18px 5%;background:#111f30;display:flex;justify-content:space-between}.brand{font-size:23px;font-weight:800}.brand span{color:#71d5a0}main{max-width:1100px;margin:28px auto;padding:0 18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{background:#142338;border:1px solid #2b4058;border-radius:16px;padding:20px}input,textarea,select{box-sizing:border-box;width:100%;padding:11px;margin:6px 0 12px;border-radius:8px;border:1px solid #40546b;background:#0b1829;color:#fff}label{font-size:13px;color:#a9bbce}.btn{background:#71d5a0;color:#092018;border:0;padding:11px 16px;border-radius:9px;font-weight:800;cursor:pointer}.item{padding:12px 0;border-bottom:1px solid #2b4058}.muted{color:#9db0c4}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><header><div class="brand">Auto<span>Flow</span> / Партнёр</div><a href="/marketplace" style="color:#b8c9d8">Каталог</a></header><main><h1>Кабинет автосервиса</h1><p class="muted">Заполните профиль и добавьте услуги. После проверки профиль появится в каталоге.</p><div class="grid"><section class="panel"><h2>Публичный профиль</h2><form id="profile"><label>Название автосервиса</label><input name="public_name" required><label>Город</label><input name="city" value="Санкт-Петербург" required><label>Район</label><input name="district"><label>Адрес</label><input name="address" required><label>Телефон</label><input name="phone" required><label>Описание</label><textarea name="description"></textarea><label>Сайт</label><input name="website"><button class="btn">Сохранить профиль</button></form><p id="profilemsg" class="muted"></p></section><section class="panel"><h2>Добавить услугу</h2><form id="service"><label>Название услуги</label><input name="title" required><label>Категория</label><select name="category"><option>ТО</option><option>Диагностика</option><option>Ремонт двигателя</option><option>Шиномонтаж</option><option>Тормозная система</option><option>Электрика</option><option>Кузовной ремонт</option><option>Другое</option></select><label>Цена от, ₽</label><input name="price_from_rub" type="number" min="0"><label>Длительность, минут</label><input name="duration_minutes" type="number" min="15" max="1440" value="60"><label>Описание</label><textarea name="description"></textarea><button class="btn">Добавить услугу</button></form><div id="services"></div></section><section class="panel" style="grid-column:1/-1"><h2>Заявки на запись</h2><div id="bookings" class="muted">Загрузка…</div></section></div></main>
<script>const $=s=>document.querySelector(s);async function api(url,opt={}){let r=await fetch(url,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'Ошибка запроса');return d}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function load(){try{let p=await api('/api/partner/profile');if(p)for(let [k,v] of Object.entries({public_name:p.name,city:p.city,district:p.district,address:p.address,phone:p.phone,description:p.description,website:p.website}))$('#profile').elements[k].value=v||'';let services=await api('/api/partner/services');$('#services').innerHTML=services.map(s=>'<div class="item"><b>'+esc(s.title)+'</b><div class="muted">'+esc(s.category)+' · '+(s.price_from_rub??'цена по запросу')+' ₽ · '+s.duration_minutes+' мин</div></div>').join('');let bookings=await api('/api/partner/bookings');$('#bookings').innerHTML=bookings.length?bookings.map(b=>'<div class="item"><b>'+esc(b.customer_name)+' · '+esc(b.service)+'</b><div class="muted">'+esc(b.customer_phone)+' · '+new Date(b.starts_at).toLocaleString('ru-RU')+' · '+esc(b.status)+'</div><div class="row">'+(b.status==='pending'?'<button class="btn" onclick="status('+b.id+',\'confirmed\')">Подтвердить</button>':'')+(b.status==='pending'||b.status==='confirmed'?'<button class="btn" onclick="status('+b.id+',\'cancelled\')">Отменить</button>':'')+'</div></div>').join(''):'Пока заявок нет.'}catch(e){$('#bookings').textContent=e.message+' — сначала войдите в аккаунт на главной странице.'}}async function status(id,s){try{await api('/api/partner/bookings/'+id,{method:'PATCH',body:JSON.stringify({status:s})});load()}catch(e){alert(e.message)}}$('#profile').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{let p=await api('/api/partner/profile',{method:'PUT',body:JSON.stringify(d)});$('#profilemsg').textContent=p.is_published?'Профиль сохранён и опубликован':'Профиль сохранён. Ожидает проверки администратора.'}catch(e){$('#profilemsg').textContent=e.message}};$('#service').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.price_from_rub=d.price_from_rub?Number(d.price_from_rub):null;d.duration_minutes=Number(d.duration_minutes);try{await api('/api/partner/services',{method:'POST',body:JSON.stringify(d)});e.target.reset();load()}catch(e){alert(e.message)}};load();</script></body></html>
"""

PLATFORM = r"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoFlow — управление платформой</title>
<style>body{margin:0;background:#0b1421;color:#eaf0f7;font:15px Inter,Segoe UI,Arial}header{padding:18px 5%;background:#111f30}.brand{font-size:23px;font-weight:800}.brand span{color:#71d5a0}main{max-width:1200px;margin:28px auto;padding:0 18px}.stats,.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.panel{background:#142338;border:1px solid #2b4058;border-radius:15px;padding:18px}.stat b{display:block;font-size:28px;margin-top:8px}.grid{grid-template-columns:1fr 1fr;margin-top:16px}.item{padding:13px 0;border-bottom:1px solid #2b4058}.muted{color:#9db0c4}.btn{background:#71d5a0;color:#092018;border:0;padding:8px 12px;border-radius:8px;font-weight:800;cursor:pointer}@media(max-width:750px){.stats,.grid{grid-template-columns:1fr 1fr}}@media(max-width:500px){.stats,.grid{grid-template-columns:1fr}}</style></head><body><header><div class="brand">Auto<span>Flow</span> / Администрирование</div></header><main><h1>Панель платформы</h1><div id="stats" class="stats"></div><div class="grid"><section class="panel"><h2>Автосервисы</h2><div id="businesses">Загрузка…</div></section><section class="panel"><h2>Заявки и клиенты</h2><div id="bookings">Загрузка…</div></section></div></main><script>const $=s=>document.querySelector(s);async function api(url,opt={}){let r=await fetch(url,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'Нет доступа или ошибка запроса');return d}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function load(){try{let [o,b,book,clients]=await Promise.all([api('/api/platform/overview'),api('/api/platform/businesses'),api('/api/platform/bookings'),api('/api/platform/clients')]);$('#stats').innerHTML=[['Организации',o.organizations],['Опубликовано',o.published_businesses],['Клиенты',o.customers],['Заявки',o.booking_requests],['Ожидают подтверждения',o.pending_bookings]].map(x=>'<div class="stat"><span class="muted">'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');$('#businesses').innerHTML=b.length?b.map(x=>'<div class="item"><b>'+esc(x.name)+'</b><div class="muted">'+esc(x.city)+' · '+esc(x.address)+' · услуг: '+x.services_count+'</div><div class="muted">'+x.services.map(s=>esc(s.title)).join(', ')+'</div><button class="btn" onclick="publish('+x.organization_id+')">'+(x.is_published?'Снять с публикации':'Опубликовать')+'</button></div>').join(''):'Пока нет профилей';$('#bookings').innerHTML='<h3>Заявки</h3>'+(book.length?book.map(x=>'<div class="item"><b>'+esc(x.customer_name)+' · '+esc(x.business)+'</b><div class="muted">'+esc(x.customer_phone)+' · '+esc(x.service)+' · '+new Date(x.starts_at).toLocaleString('ru-RU')+' · '+esc(x.status)+'</div></div>').join(''):'Заявок пока нет')+'<h3>Клиенты автосервисов</h3>'+(clients.length?clients.map(x=>'<div class="item"><b>'+esc(x.name)+'</b><div class="muted">'+esc(x.organization)+' · '+esc(x.phone||x.email||'Контакты не указаны')+'</div></div>').join(''):'Клиентов пока нет')}catch(e){$('#stats').textContent=e.message+'; настройте PLATFORM_ADMIN_EMAIL и войдите администратором.'}}async function publish(id){try{await api('/api/platform/businesses/'+id+'/publish',{method:'PATCH'});load()}catch(e){alert(e.message)}}load();</script></body></html>
"""

@router.get("/partner", response_class=HTMLResponse, include_in_schema=False)
def partner_home():
    return PARTNER

@router.get("/platform", response_class=HTMLResponse, include_in_schema=False)
def platform_home():
    return PLATFORM
